package org.stackdocs.app;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.SystemClock;
import android.view.*;
import android.widget.TextView;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import java.util.zip.*;

final class P1BatchChecks {
    static void run(Instrumentation instrumentation,Consumer<String> mark)throws Exception {
        Context target=instrumentation.getTargetContext();P1Checks.require(target.getPackageName().equals("org.stackdocs.app.checks"),"Disposable batch package required");target.getSharedPreferences("local_policy",Context.MODE_PRIVATE).edit().putBoolean("app_lock",false).commit();StackApplication app=(StackApplication)target.getApplicationContext();instrumentation.runOnMainSync(() -> {});P1BatchChecks.await(() -> app.library!=null&&app.batches!=null&&app.metadata!=null&&app.ocr!=null&&app.suggestions!=null,"Application startup");app.io.submit(() -> {}).get();
        Uri valid=Uri.parse("content://"+instrumentation.getContext().getPackageName()+".fixtures/valid"),denied=Uri.parse("content://"+instrumentation.getContext().getPackageName()+".fixtures/denied");
        int before=app.io.submit(() -> app.library.documents("",null).size()).get();ArrayBlockingQueue<String> created=new ArrayBlockingQueue<>(1);instrumentation.runOnMainSync(() -> app.batches.importUris(Arrays.asList(valid,denied,valid),created::offer));String op=created.poll(10,TimeUnit.SECONDS);P1Checks.require(op!=null,"Durable batch created");await(() -> terminal(app,op),"Mixed batch completes");
        BatchStore.Operation mixed=app.io.submit(() -> app.library.batches.operation(op)).get();P1Checks.require(mixed.state.equals("failed")&&mixed.items.get(0).state.equals("done")&&mixed.items.get(1).state.equals("failed")&&mixed.items.get(2).state.equals("done"),"Per-item mixed result");P1Checks.require(app.io.submit(() -> app.library.documents("",null).size()).get()==before+2,"Only valid sources saved");
        instrumentation.runOnMainSync(() -> app.batches.retry(op));await(() -> terminal(app,op),"Retry completes");P1Checks.require(app.io.submit(() -> app.library.documents("",null).size()).get()==before+2,"Retry never duplicates successful imports");
        List<String> ids=Arrays.asList(mixed.items.get(0).document,mixed.items.get(2).document);app.io.submit(() -> {for(String id:ids)app.library.rename(id,"Duplicate / synthetic title");}).get();
        long start=SystemClock.elapsedRealtime();String zip=app.io.submit(() -> {String id=app.library.batches.create("zip",ids,ids);app.batches.run(id);return id;}).get();await(() -> terminal(app,zip),"ZIP export");P1Checks.require(app.io.submit(() -> app.library.batches.operation(zip).state.equals("done")).get(),"ZIP export done");long zipMs=SystemClock.elapsedRealtime()-start;Uri zipUri=app.batches.outputs.get(zip).get(0);
        int entries=0;try(ZipInputStream input=new ZipInputStream(target.getContentResolver().openInputStream(zipUri))){ZipEntry entry;Set<String> names=new HashSet<>();while((entry=input.getNextEntry())!=null){P1Checks.require(!entry.getName().contains("/")&&names.add(entry.getName()),"Safe unique deterministic PDF names");ByteArrayOutputStream bytes=new ByteArrayOutputStream();LibraryRepository.copy(input,bytes,256L*1024*1024);String id=ids.get(entries++);byte[] original=app.io.submit(() -> ScannerChecks.bytes(app.library.source(app.library.document(id)))).get();P1Checks.require(Arrays.equals(original,bytes.toByteArray()),"Ordered untouched PDF bytes in ZIP");}}P1Checks.require(entries==2,"All selected PDFs in ZIP");
        mark.accept("Durable mixed provider batch: 2 saved/1 denied, retry without duplicates; ordered ZIP has 2 safe unique PDF names and byte-identical originals; zip_ms="+zipMs);
        // Actual separate UID requester, visible user-selected PDF only, cancellation and MIME mismatch.
        String chosen=ids.get(0);app.io.submit(() -> app.library.rename(chosen,"P1 external request")).get();ArrayBlockingQueue<Intent> replies=new ArrayBlockingQueue<>(1);IsolatedCheckActivity.content=activity -> new TextView(activity);IsolatedCheckActivity.result=(request,data) -> {if(data!=null)replies.offer(data);};
        Activity host=instrumentation.startActivitySync(new Intent(target,IsolatedCheckActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        try {
            Instrumentation.ActivityMonitor monitor=instrumentation.addMonitor(PdfSelectionActivity.class.getName(),null,false);
            request(instrumentation,host,"application/pdf");Activity selection=monitor.waitForActivityWithTimeout(10000);P1Checks.require(selection!=null,"Exported GET_CONTENT opens");Activity first=selection;await(() -> hasText(instrumentation,first,"P1 external request"),"Selected document button ready");instrumentation.runOnMainSync(() -> click(first.getWindow().getDecorView(),"P1 external request"));Intent reply=replies.poll(30,TimeUnit.SECONDS);P1Checks.require(reply!=null&&reply.getIntExtra("result_code",0)==Activity.RESULT_OK&&reply.getIntExtra("uid",0)!=android.os.Process.myUid()&&reply.getBooleanExtra("read_only",false)&&reply.getLongExtra("bytes",0)>100&&reply.getStringExtra("mime").equals("application/pdf"),"Actual separate-UID PDF result and read-only grant: "+(reply==null?"no reply; chooser="+dump(instrumentation,first)+threads():reply.getExtras()));
            instrumentation.removeMonitor(monitor);Instrumentation.ActivityMonitor cancelMonitor=instrumentation.addMonitor(PdfSelectionActivity.class.getName(),null,false);
            request(instrumentation,host,"application/pdf");selection=cancelMonitor.waitForActivityWithTimeout(10000);P1Checks.require(selection!=null,"Second selection opens");Activity cancel=selection;instrumentation.runOnMainSync(cancel::onBackPressed);reply=replies.poll(10,TimeUnit.SECONDS);P1Checks.require(reply!=null&&reply.getIntExtra("result_code",1)==Activity.RESULT_CANCELED&&!reply.hasExtra("uri"),"Cancel exposes no URI: "+(reply==null?"no reply":reply.getExtras()));instrumentation.removeMonitor(cancelMonitor);
            request(instrumentation,host,"image/jpeg");reply=replies.poll(10,TimeUnit.SECONDS);P1Checks.require(reply!=null&&reply.getIntExtra("result_code",1)==Activity.RESULT_CANCELED,"Explicit MIME mismatch rejected");
            mark.accept("Actual separate-UID GET_CONTENT PDF request: user-selected output readable and read-only, malicious incoming path ignored; cancellation and MIME mismatch return no document");
        }finally{instrumentation.runOnMainSync(host::finish);IsolatedCheckActivity.content=null;IsolatedCheckActivity.result=null;}
        String keep=app.io.submit(() -> app.library.importDocument(valid).id).get();String deletion=app.io.submit(() -> {String id=app.library.batches.create("delete",ids,ids);app.batches.run(id);return id;}).get();await(() -> terminal(app,deletion),"Batch delete");P1Checks.require(app.io.submit(() -> !app.library.batches.exists(ids.get(0))&&!app.library.batches.exists(ids.get(1))&&app.library.batches.exists(keep)).get(),"Only selected documents deleted");
        // Synthetic consent boundary, not real MediaStore permission/collection.
        int count=app.io.submit(() -> app.library.documents("",null).size()).get();boolean disabled=app.io.submit(() -> {try{app.library.importDocument(valid,UUID.randomUUID().toString(),"Blocked future photo",() -> false,new Object());return false;}catch(IOException expected){return true;}}).get();P1Checks.require(disabled&&app.io.submit(() -> app.library.documents("",null).size()).get()==count,"Disable boundary rejects unsaved original before metadata commit");
        mark.accept("Scoped batch delete preserves unselected identity; synthetic photo-disable predicate rejects commit without a new document (actual MediaStore/permission/notification handling remains H4)");
    }
    static void await(Callable<Boolean> condition,String label)throws Exception{long end=SystemClock.elapsedRealtime()+90000;while(SystemClock.elapsedRealtime()<end){if(condition.call())return;Thread.sleep(50);}throw new AssertionError(label);}
    private static boolean terminal(StackApplication app,String id)throws Exception{return app.io.submit(() -> {String state=app.library.batches.operation(id).state;return state.equals("done")||state.equals("failed")||state.equals("canceled");}).get();}
    private static void request(Instrumentation instrumentation,Activity host,String mime){Intent intent=new Intent().setClassName(instrumentation.getContext().getPackageName(),PdfRequestProbeActivity.class.getName()).putExtra("target",instrumentation.getTargetContext().getPackageName()).putExtra("mime",mime);instrumentation.runOnMainSync(() -> host.startActivityForResult(intent,92));}
    private static String threads(){StringBuilder out=new StringBuilder();for(java.util.Map.Entry<Thread,StackTraceElement[]> entry:Thread.getAllStackTraces().entrySet()){boolean relevant=false;for(StackTraceElement frame:entry.getValue())if(frame.getClassName().startsWith("org.stackdocs"))relevant=true;if(relevant){out.append("\nThread ").append(entry.getKey().getName());for(StackTraceElement frame:entry.getValue())out.append("\n ").append(frame);}}return out.toString();}
    private static String dump(Instrumentation instrumentation,Activity activity){StringBuilder out=new StringBuilder();instrumentation.runOnMainSync(() -> dumpView(activity.getWindow().getDecorView(),out));return out.toString();}
    private static void dumpView(View view,StringBuilder out){if(view instanceof TextView)out.append('[').append(((TextView)view).getText()).append(']');if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)dumpView(((ViewGroup)view).getChildAt(i),out);}
    private static boolean hasText(Instrumentation i,Activity activity,String needle){boolean[] found={false};i.runOnMainSync(() -> found[0]=find(activity.getWindow().getDecorView(),needle)!=null);return found[0];}
    private static View find(View view,String needle){if(view instanceof TextView&&((TextView)view).getText().toString().startsWith(needle))return view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int j=0;j<group.getChildCount();j++){View found=find(group.getChildAt(j),needle);if(found!=null)return found;}}return null;}
    private static void click(View root,String needle){View view=find(root,needle);P1Checks.require(view!=null,"Button found");view.performClick();}
}
